#!/usr/bin/env node
/**
 * Generates strict-mode TypeScript definitions from the Soroban contract XDR ABI
 * in `packages/sdk/abi/plimsoll.abi.json`.
 *
 * Usage:
 *   node scripts/codegen-abi.mjs          # write src/generated/contract-types.ts
 *   node scripts/codegen-abi.mjs --check  # exit 1 if generated file is out of date
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { xdr } from "@stellar/stellar-sdk";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const sdkRoot = path.resolve(__dirname, "..");
const abiPath = path.join(sdkRoot, "abi", "plimsoll.abi.json");
const outPath = path.join(sdkRoot, "src", "generated", "contract-types.ts");

function xdrStr(val) {
  if (typeof val === "string") return val;
  if (val && typeof val.toString === "function") return val.toString();
  return String(val ?? "");
}

function toCamelCase(snake) {
  return snake.replace(/_([a-z0-9])/g, (_, ch) => ch.toUpperCase());
}

function toPascalCase(name) {
  const camel = toCamelCase(name);
  return camel.charAt(0).toUpperCase() + camel.slice(1);
}

function mapTypeDef(typeDef) {
  switch (typeDef.type) {
    case "scSpecTypeVoid":
      return "void";
    case "scSpecTypeBool":
      return "boolean";
    case "scSpecTypeU32":
    case "scSpecTypeI32":
    case "scSpecTypeU64":
    case "scSpecTypeI64":
      return "number";
    case "scSpecTypeU128":
    case "scSpecTypeI128":
    case "scSpecTypeU256":
    case "scSpecTypeI256":
    case "scSpecTypeTimepoint":
    case "scSpecTypeDuration":
      return "bigint";
    case "scSpecTypeString":
    case "scSpecTypeSymbol":
    case "scSpecTypeAddress":
    case "scSpecTypeBytes":
    case "scSpecTypeBytesN":
      return "string";
    case "scSpecTypeOption":
      return `${mapTypeDef(typeDef.option.valueType)} | undefined`;
    case "scSpecTypeVec":
      return `readonly (${mapTypeDef(typeDef.vec.elementType)})[]`;
    case "scSpecTypeResult": {
      const ok = mapTypeDef(typeDef.result.okType);
      const err = mapTypeDef(typeDef.result.errorType);
      return `{ ok: ${ok} } | { err: ${err} }`;
    }
    case "scSpecTypeTuple": {
      const elems = typeDef.tuple.valueTypes.map(mapTypeDef);
      return `readonly [${elems.join(", ")}]`;
    }
    case "scSpecTypeMap": {
      const k = mapTypeDef(typeDef.map.keyType);
      const v = mapTypeDef(typeDef.map.valueType);
      return `ReadonlyMap<${k}, ${v}>`;
    }
    case "scSpecTypeUdt":
      return xdrStr(typeDef.udt.name);
    default:
      throw new Error(`Unsupported ScSpecTypeDef: ${typeDef.type}`);
  }
}

function formatDoc(doc, indent = "") {
  const text = xdrStr(doc).trim();
  if (!text) return "";
  return `${indent}/** ${text} */\n`;
}

function emitEnum(spec) {
  const name = xdrStr(spec.name);
  const doc = formatDoc(spec.doc);
  const cases = spec.cases
    .map((c) => {
      const cDoc = formatDoc(c.doc, "  ");
      return `${cDoc}  ${xdrStr(c.name)} = ${c.value},`;
    })
    .join("\n");
  return `${doc}export enum ${name} {\n${cases}\n}`;
}

function emitStruct(spec) {
  const name = xdrStr(spec.name);
  const doc = formatDoc(spec.doc);
  const fields = spec.fields
    .map((f) => {
      const fDoc = formatDoc(f.doc, "  ");
      const fName = toCamelCase(xdrStr(f.name));
      const fType = mapTypeDef(f.type);
      return `${fDoc}  ${fName}: ${fType};`;
    })
    .join("\n");
  return `${doc}export interface ${name} {\n${fields}\n}`;
}

function emitFnEntry(spec) {
  const fnName = xdrStr(spec.name);
  const doc = formatDoc(spec.doc, "  ");
  const args = spec.inputs
    .map((inp) => `${toCamelCase(xdrStr(inp.name))}: ${mapTypeDef(inp.type)}`)
    .join("; ");
  const ret =
    spec.outputs.length === 0
      ? "void"
      : spec.outputs.length === 1
        ? mapTypeDef(spec.outputs[0])
        : `readonly [${spec.outputs.map(mapTypeDef).join(", ")}]`;
  return `${doc}  ${fnName}: {\n    args: { ${args} };\n    return: ${ret};\n  };`;
}

function generate() {
  const raw = JSON.parse(fs.readFileSync(abiPath, "utf8"));
  const blocks = [
    "// DO NOT EDIT — generated by scripts/codegen-abi.mjs from abi/plimsoll.abi.json",
    "// Run `npm run codegen -w @plimsoll/sdk` to regenerate.",
    "",
  ];

  const fnInterfaces = [];

  for (const [contractName, entries] of Object.entries(raw.contracts)) {
    const fns = [];
    for (const b64 of entries) {
      const entry = xdr.ScSpecEntry.fromXDR(b64, "base64");
      switch (entry.type) {
        case "scSpecEntryUdtEnumV0":
          blocks.push(emitEnum(entry.udtEnumV0), "");
          break;
        case "scSpecEntryUdtStructV0":
          blocks.push(emitStruct(entry.udtStructV0), "");
          break;
        case "scSpecEntryFunctionV0":
          fns.push(entry.functionV0);
          break;
        default:
          throw new Error(`Unsupported ScSpecEntry type: ${entry.type}`);
      }
    }
    if (fns.length > 0) {
      const ifaceName = `${toPascalCase(contractName)}Fns`;
      fnInterfaces.push(ifaceName);
      const body = fns.map(emitFnEntry).join("\n");
      blocks.push(
        `/** Contract function signatures for ${contractName}. */\nexport interface ${ifaceName} {\n${body}\n}`,
        "",
      );
    }
  }

  if (fnInterfaces.length > 0) {
    blocks.push(
      `/** All contract function signatures keyed by contract. */\nexport interface PlimsollContractFns {\n${fnInterfaces
        .map((n) => `  ${n.charAt(0).toLowerCase() + n.slice(1).replace(/Fns$/, "")}: ${n};`)
        .join("\n")}\n}`,
      "",
    );
  }

  return blocks.join("\n");
}

const isCheck = process.argv.includes("--check");
let generated = generate();
try {
  const prettier = await import("prettier");
  generated = await prettier.format(generated, { filepath: outPath });
} catch {
  // prettier is optional outside monorepo dev
}

if (isCheck) {
  const existing = fs.existsSync(outPath) ? fs.readFileSync(outPath, "utf8") : "";
  if (existing !== generated) {
    console.error(
      `Generated types in ${path.relative(sdkRoot, outPath)} are out of date. Run \`npm run codegen -w @plimsoll/sdk\`.`,
    );
    process.exit(1);
  }
  console.log("Generated contract types are up to date.");
} else {
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, generated);
  console.log(`Wrote ${path.relative(sdkRoot, outPath)}`);
}
